// Test signals, generated by the same formula as models/Audio_Emotion_Analysis/make_fixtures.py.
// The fixtures record a checksum of each signal, and helpers.ts checks it, so a drift between the
// two generators fails the tests instead of silently comparing different audio.

const TWO_PI = 2 * Math.PI;

export const SIGNALS: Record<string, { size: number; seed: number }> = {
    voiced: { size: 3.2, seed: 11 },
    quiet: { size: 3.0, seed: 12 },
    tone: { size: 2.5, seed: 13 },
    late_loud: { size: 3.5, seed: 14 },
    burst: { size: 2.6, seed: 15 },
    silence: { size: 2.0, seed: 16 },
    short: { size: 1000, seed: 17 }, // a fixed number of samples
    half_second: { size: 0.45, seed: 18 },
};

export function lcg(seed: number) {
    let state = seed >>> 0;
    return () => {
        state = (Math.imul(1664525, state) + 1013904223) >>> 0;
        return (state / 4294967296) * 2 - 1;
    };
}

const voiced = (t: number) => {
    const syllable = Math.sin(TWO_PI * 2.2 * t);
    const envelope = syllable > 0 ? syllable : 0;
    const phase = TWO_PI * (150 * t + 12 * Math.sin(TWO_PI * 0.9 * t));
    return envelope * (Math.sin(phase) + 0.5 * Math.sin(2 * phase) + 0.25 * Math.sin(3 * phase));
};

function value(name: string, t: number, noise: number): number {
    switch (name) {
        case "voiced":
        case "short":
        case "half_second":
            return 0.35 * voiced(t) + 0.02 * noise;
        case "quiet":
            return 0.004 * noise;
        case "tone":
            return 0.3 * Math.sin(TWO_PI * 220 * t);
        case "late_loud":
            return t < 2.4 ? 0.003 * noise : 0.5 * voiced(t) + 0.02 * noise;
        case "burst":
            return t < 0.35 ? 0.4 * Math.sin(TWO_PI * 300 * t) : 0;
        case "silence":
            return 0;
        default:
            throw new Error(`unknown signal ${name}`);
    }
}

function wave(name: string, rate: number): number[] {
    const { size, seed } = SIGNALS[name];
    const n = Number.isInteger(size) && size >= 1000 ? size : Math.floor(size * rate);
    const noise = lcg(seed);
    const out = new Array<number>(n);
    for (let i = 0; i < n; i++) out[i] = value(name, i / rate, noise());
    return out;
}

export const float32Signal = (name: string, rate: number) => Float32Array.from(wave(name, rate));

export const int16Signal = (name: string, rate: number) =>
    Int16Array.from(wave(name, rate), (v) => Math.max(-32768, Math.min(32767, Math.floor(v * 32768 + 0.5))));

/** The sum of the raw bits modulo 2**32, as in make_fixtures.py. */
export function checksum(array: Float32Array | Int16Array): number {
    const bits = array instanceof Float32Array ? new Uint32Array(array.buffer, array.byteOffset, array.length) : new Uint16Array(array.buffer, array.byteOffset, array.length);
    let sum = 0;
    for (let i = 0; i < bits.length; i++) sum = (sum + bits[i]) % 4294967296;
    return sum;
}

/** 16-bit samples as the float values librosa reads from a 16-bit WAV. */
export const int16ToFloat = (pcm: Int16Array) => Float32Array.from(pcm, (v) => v / 32768);
